import openpyxl
wb = openpyxl.load_workbook('init.xlsx', data_only=True)
ws1 = wb['Sheet1']
ws2 = wb['Sheet2']

# Sheet2 headers in column order
header_cols = []  # (header, list of values)
for c in range(1, ws2.max_column+1):
    h = ws2.cell(1, c).value
    if h:
        vals = []
        for r in range(2, ws2.max_row+1):
            v = ws2.cell(r, c).value
            if v:
                vals.append(v)
        header_cols.append((h, vals))

# Sheet1 entries
entries = []
for r in range(2, ws1.max_row+1):
    entries.append(ws1.cell(r,1).value)

output = []
# group by header in Sheet2 column order, entries in Sheet1 row order
for h, vals in header_cols:
    for entry in entries:
        parts = entry.split('+')
        if len(parts) >= 3 and parts[2] == h:
            prefix, relation, header, prop = parts[0], parts[1], parts[2], parts[3]
            for v in vals:
                output.append(prefix+'+'+relation+'+'+header+'+'+prop+'+'+v)

print('total data rows:', len(output))
for i,o in enumerate(output[:55],1):
    print(i, o)
EOF
